sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
  api,
  event,
  helpers,
  imports
}) {



  const timeoutId = helpers.timing.setTimeout(() => {
    var req = api.state.reqId;
    console.log("reqid is " + req + " and ritm req id is " + api.data.getRITM.results[0].request.value);
    if (req != api.data.getRITM.results[0].request.value) {
        api.setState('ritmId', '');
        return;
    } else {
        api.setState('ritmId', api.data.getRITM.results[0]._row_data.uniqueValue);
        api.setState('hideRITMButton', false);
    }  }, 1 * 1000);





}
